using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// RISC-V 转译器
    /// </summary>
    public class TranslatorRISCV : Translator32bit
    {
        public override string ARCH_NAME => "RISCV";

        protected override string[] ContextRegNames() => new[] { "ra", "a0", "a1", "a2", "a3", "t0", "t1", "t2", "t3", "s0", "s1", "s2", "s3", "s4", "s5" };
        protected override string NativeIret() => "mret";
        protected override string NativeCli() => "csrrc x0, mstatus, 0x8";
        protected override string NativeSti() => "csrrs x0, mstatus, 0x8";
        protected override void EmitNativeInt(int vector)
        {
            Emit($"    li a7, {vector}");
            Emit("    ecall");
        }
        protected override void EmitSaveContext()
        {
            Emit("    addi sp, sp, -64");
            int off = 0;
            foreach (var r in ContextRegNames())
            {
                Emit($"    sw {r}, {off}(sp)");
                off += 4;
            }
        }
        protected override void EmitRestoreContext()
        {
            int off = 0;
            foreach (var r in ContextRegNames())
            {
                Emit($"    lw {r}, {off}(sp)");
                off += 4;
            }
            Emit("    addi sp, sp, 64");
        }

        // RISC-V ABI 寄存器映射 (VML CCv2 → RV32G)
        // R0-R3 = args/return → a0-a3 (x10-x13)
        // R4-R11 = temporaries → t0-t6/s1-s2 (x5-x7, x28-x31)
        // R12 = BP → s0/fp (x8)
        // R13 = SP → sp (x2)
        // R14 = 临时 → t3/a4 (x15/x14)
        // R15 = RA → ra (x1)
        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "a0" },    // VML R0 = arg0/retval
            { 1, "a1" },    // VML R1 = arg1
            { 2, "a2" },    // VML R2 = arg2
            { 3, "a3" },    // VML R3 = arg3
            { 4, "t0" },    // VML R4 = temp
            { 5, "t1" },    // VML R5 = temp
            { 6, "t2" },    // VML R6 = temp
            { 7, "t3" },    // VML R7 = temp
            { 8, "s0" },    // VML R8 = saved
            { 9, "s1" },    // VML R9 = saved
            { 10, "s2" },   // VML R10 = saved
            { 11, "s3" },   // VML R11 = saved
            { 12, "s4" },   // VML R12 = BP (caller-saved in CCv2)
            { 13, "sp" },   // VML R13 = SP
            { 14, "s5" },   // VML R14 = temp
            { 15, "ra" },   // VML R15 = RA (return address)
        };

        public TranslatorRISCV(VmlProgram vmlProgram) : base(vmlProgram)
        {}

        protected override void EmitHeader()
        {
            Emit("# RISC-V Assembly - Translated from VML");
            Emit("# Generated by VML Translator");
            Emit("");
            Emit(".data");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is DataString ds)
                    {
                        string escaped = EscapeString(ds.Value);
                        Emit($"{name}: .asciz \"{escaped}\"");
                    }
                    else if (value is string strValue)
                    {
                        string escaped = EscapeString(strValue);
                        Emit($"{name}: .asciz \"{escaped}\"");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        string vals = string.Join(", ", listValue);
                        Emit($"{name}: .word {vals}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name}: .word {intValue}");
                    }
                }
            }
            Emit("");
            Emit(".text");
            Emit(".globl main");
            Emit("");
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.DIV:
                    TranslateDiv(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.PUSH:
                    TranslatePush(instr);
                    break;
                case OpCode.POP:
                    TranslatePop(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"    j {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"    beqz {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"    bnez {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JE:
                    Emit($"    beq x0, x0, {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"    bne x0, x0, {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"    blt x0, x1, {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"    ble x0, x1, {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"    bgt x0, x1, {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"    bge x0, x1, {instr.Operands[0].Value}");
                    break;
                case OpCode.CALL:
                    Emit($"    jal {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("    ret");
                    break;
                case OpCode.HALT:
                    TranslateHalt();
                    break;
                case OpCode.NOP:
                    Emit("    nop");
                    break;
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit($"    li a0, {GetOperandValue(instr.Operands[0])}");
                    Emit("    ecall");
                    break;
                case OpCode.CATCH:
                    Emit($"    la t0, {instr.Operands[0].Value}");
                    Emit("    csrw mtvec, t0");
                    break;
                case OpCode.ENDCATCH:
                    Emit("    csrw mtvec, x0");
                    break;

                // 浮点运算指令 (RISC-V F/D 扩展)
                case OpCode.FADD:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit($"    flw f1, {GetOperandValue(instr.Operands[2])}, x0");
                    Emit("    fadd.s f2, f0, f1");
                    Emit($"    fsw f2, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.FSUB:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit($"    flw f1, {GetOperandValue(instr.Operands[2])}, x0");
                    Emit("    fsub.s f2, f0, f1");
                    Emit($"    fsw f2, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.FMUL:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit($"    flw f1, {GetOperandValue(instr.Operands[2])}, x0");
                    Emit("    fmul.s f2, f0, f1");
                    Emit($"    fsw f2, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.FDIV:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit($"    flw f1, {GetOperandValue(instr.Operands[2])}, x0");
                    Emit("    fdiv.s f2, f0, f1");
                    Emit($"    fsw f2, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.FNEG:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[0])}, x0");
                    Emit("    fneg.s f0, f0");
                    Emit($"    fsw f0, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.FCMP:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[0])}, x0");
                    Emit($"    flw f1, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit("    feq.s t0, f0, f1");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit($"    fcvt.s.w f0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    fsw f0, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.F2I:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit("    fcvt.w.s t0, f0, rtz");
                    Emit($"    sw t0, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.F2D:
                    Emit($"    flw f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit("    fcvt.d.s f0, f0");
                    Emit($"    fsd f0, {GetOperandValue(instr.Operands[0])}, x0");
                    break;
                case OpCode.D2F:
                    Emit($"    fld f0, {GetOperandValue(instr.Operands[1])}, x0");
                    Emit("    fcvt.s.d f0, f0");
                    Emit($"    fsw f0, {GetOperandValue(instr.Operands[0])}, x0");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    Emit("    addi sp, sp, -4");
                    Emit("    fsw f0, 0(sp)");
                    break;
                case OpCode.FPOP:
                    Emit("    flw f0, 0(sp)");
                    Emit("    addi sp, sp, 4");
                    break;

                // --- 缺失的指令补全 ---

                // 位运算指令
                case OpCode.AND:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    andi x5, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                        Emit($"    mv {MapRegister((int)instr.Operands[0].Value)}, x5");
                    }
                    else
                    {
                        Emit($"    and {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.OR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    ori x5, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                        Emit($"    mv {MapRegister((int)instr.Operands[0].Value)}, x5");
                    }
                    else
                    {
                        Emit($"    or {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.XOR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    xori x5, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                        Emit($"    mv {MapRegister((int)instr.Operands[0].Value)}, x5");
                    }
                    else
                    {
                        Emit($"    xor {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.NOT:
                    Emit($"    xori x5, {GetOperandValue(instr.Operands[0])}, -1");
                    Emit($"    mv {MapRegister((int)instr.Operands[0].Value)}, x5");
                    break;

                // 移位指令 (RV32I)
                case OpCode.SHL:
                case OpCode.SHLV:
                    if (instr.Operands.Count >= 3 && instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    slli {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    sll {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.SHRV:
                case OpCode.SHR:
                    if (instr.Operands.Count >= 3 && instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    srli {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    srl {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.ZERO:
                    Emit($"    li {MapRegister((int)instr.Operands[0].Value)}, 0");
                    break;
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 单目算术指令
                case OpCode.INC:
                    Emit($"    addi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 1");
                    break;
                case OpCode.DEC:
                    Emit($"    addi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, -1");
                    break;
                case OpCode.NEG:
                    Emit($"    neg {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;

                // 模运算: MOD = A - (A / B) * B
                case OpCode.MOD:
                    Emit($"    div x6, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    mul x6, x6, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    sub {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, x6");
                    break;

                // TEST: 与运算，结果在 x5
                case OpCode.TEST:
                    if (instr.Operands[1].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    andi x5, {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    }
                    else
                    {
                        Emit($"    and x5, {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}");
                    }
                    break;

                // 函数返回（带值）
                // case OpCode.RET_VAL:
                //     Emit($"    mv a0, {GetOperandValue(instr.Operands[0])}"); // a0 = 返回值
                //     Emit("    ret");
                //     break;

                // 标签定义
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 系统调用 (ALLOC/FREE 通过 SYSCALL 40/41)
                case OpCode.SYSCALL:
                    Emit($"    li a7, {GetOperandValue(instr.Operands[0])}");
                    Emit("    ecall");
                    break;

                                                                                case OpCode.MOVEB:
                    Emit($"    andi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0xFF");
                    break;
                case OpCode.MOVEH:
                    Emit($"    slli {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 16");
                    Emit($"    srli {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 16");
                    break;
                case OpCode.PUSHB:
                    Emit("    addi sp, sp, -4");
                    Emit($"    sw {GetOperandValue(instr.Operands[0])}, 0(sp)");
                    Emit("    andi t0, 0(sp), 0xFF");
                    break;
                case OpCode.PUSHH:
                    Emit("    addi sp, sp, -4");
                    Emit($"    sw {GetOperandValue(instr.Operands[0])}, 0(sp)");
                    Emit("    lw t0, 0(sp)");
                    Emit("    slli t0, t0, 16");
                    Emit("    srli t0, t0, 16");
                    Emit("    sw t0, 0(sp)");
                    break;
                case OpCode.POPB:
                    Emit($"    lw {GetOperandValue(instr.Operands[0])}, 0(sp)");
                    Emit("    addi sp, sp, 4");
                    Emit($"    andi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0xFF");
                    break;
                case OpCode.POPH:
                    Emit($"    lw {GetOperandValue(instr.Operands[0])}, 0(sp)");
                    Emit("    addi sp, sp, 4");
                    Emit($"    slli {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 16");
                    Emit($"    srli {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 16");
                    break;
                case OpCode.ENTER:
                    Emit($"    addi sp, sp, -{instr.Operands[0].Value}");
                    Emit("    sw ra, 0(sp)");
                    break;
                case OpCode.LEAVE:
                    Emit("    lw ra, 0(sp)");
                    Emit($"    addi sp, sp, {instr.Operands[0].Value}");
                    Emit("    jr ra");
                    break;                                case OpCode.BREAK:
                    Emit("    ebreak");
                    break;
                case OpCode.I2D:
                case OpCode.D2I:
                    Emit($"    call __{instr.Opcode.ToString().ToLower()}");
                    break;

                // ═══════════════════════════════════════════════════════
                // 符号扩展/条件移动/循环移位 (v1.66.28+)
                // ═══════════════════════════════════════════════════════
                case OpCode.SEXTB:
                    {
                        string d = GetOperandValue(instr.Operands[0]);
                        string s = GetOperandValue(instr.Operands[1]);
                        Emit($"    slli {d}, {s}, 24");
                        Emit($"    srai {d}, {d}, 24");
                    }
                    break;
                case OpCode.SEXTH:
                    {
                        string d = GetOperandValue(instr.Operands[0]);
                        string s = GetOperandValue(instr.Operands[1]);
                        Emit($"    slli {d}, {s}, 16");
                        Emit($"    srai {d}, {d}, 16");
                    }
                    break;
                case OpCode.CMOVZ:
                    {
                        string d = GetOperandValue(instr.Operands[0]);
                        string s = GetOperandValue(instr.Operands[1]);
                        Emit($"    bnez zero, 1f");
                        Emit($"    mv {d}, {s}");
                        Emit($"1:");
                    }
                    break;
                case OpCode.CMOVNZ:
                    {
                        string d = GetOperandValue(instr.Operands[0]);
                        string s = GetOperandValue(instr.Operands[1]);
                        Emit($"    beqz zero, 1f");
                        Emit($"    mv {d}, {s}");
                        Emit($"1:");
                    }
                    break;
                case OpCode.ROL:
                    {
                        string d = GetOperandValue(instr.Operands[0]);
                        string s = GetOperandValue(instr.Operands[1]);
                        string n = GetOperandValue(instr.Operands[2]);
                        Emit($"    rori {d}, {s}, {32 - int.Parse(n.TrimStart('#'))}");
                    }
                    break;
                case OpCode.ROR:
                    {
                        string d = GetOperandValue(instr.Operands[0]);
                        string s = GetOperandValue(instr.Operands[1]);
                        string n = GetOperandValue(instr.Operands[2]);
                        Emit($"    rori {d}, {s}, {n.TrimStart('#')}");
                    }
                    break;

                default:
                    Emit($"    # UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string dstReg = GetOperandValue(dst);

            if (src.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li {dstReg}, {src.Value}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                Emit($"    lw {dstReg}, {src.Value}");
            }
            else if (src.Type == OperandType.LABEL)
            {
                Emit($"    la {dstReg}, {src.Value}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string srcReg = GetOperandValue(src);

            if (dst.Type == OperandType.MEMORY)
            {
                Emit($"    sw {srcReg}, {dst.Value}");
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    addi {dstReg}, {src1Reg}, {src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    add {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                int imm = int.Parse(src2.Value.ToString());
                Emit($"    addi {dstReg}, {src1Reg}, {-imm}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    sub {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateMul(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li x5, {src2.Value}");
                Emit($"    mul {dstReg}, {src1Reg}, x5");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    mul {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateDiv(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li x5, {src2.Value}");
                Emit($"    div {GetOperandValue(dst)}, {src1Reg}, x5");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    div {GetOperandValue(dst)}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslatePush(Instruction instr)
        {
            string reg = GetOperandValue(instr.Operands[0]);
            Emit("    addi sp, sp, -4");
            Emit($"    sw {reg}, 0(sp)");
        }

        private void TranslatePop(Instruction instr)
        {
            string reg = GetOperandValue(instr.Operands[0]);
            Emit($"    lw {reg}, 0(sp)");
            Emit("    addi sp, sp, 4");
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li x5, {src2.Value}");
                Emit($"    sub x6, {src1Reg}, x5");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    sub x6, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateHalt()
        {
            Emit("    li a7, 10");
            Emit("    ecall");
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"x{regNum}";
        }

        private static string RiscVReg(int regNum) => regNum switch
        {
            0 => "a0", 1 => "a1", 2 => "a2", 3 => "a3",
            4 => "t0", 5 => "t1", 6 => "t2", 7 => "t3",
            8 => "s0", 9 => "s1", 10 => "s2", 11 => "s3",
            12 => "s4", 13 => "sp", 14 => "s5", 15 => "ra",
            _ => $"x{regNum}"
        };

        // RISC-V GAS 不使用 # 前缀，立即数直接写值
        protected override bool UseImmediateHash => false;
    }
}
